import{_ as a,o as s,c as r,a3 as t}from"./chunks/framework.BTt0kA_k.js";const i="/RelayPulse/screenshots/user/iq-history.webp",o="/RelayPulse/screenshots/user/iq-results.webp",p="/RelayPulse/screenshots/user/iq-output.webp",g=JSON.parse('{"title":"测试历史与输出回放","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/iq-history.md","filePath":"user/use/iq-history.md"}'),u={name:"user/use/iq-history.md"};function l(n,e,c,h,f,d){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="测试历史与输出回放" tabindex="-1">测试历史与输出回放 <a class="header-anchor" href="#测试历史与输出回放" aria-label="Permalink to &quot;测试历史与输出回放&quot;">​</a></h1><p>入口：<strong>测试 → 历史记录</strong>。查看整场智商测试以及其中每个调用的输出。</p><h2 id="查找一次测试" tabindex="-1">查找一次测试 <a class="header-anchor" href="#查找一次测试" aria-label="Permalink to &quot;查找一次测试&quot;">​</a></h2><p>按测试日期、站点 / 模型和执行结果筛选。执行结果包括全部成功、部分失败、全部失败和已中止，列表支持分页。</p><p>“全部成功”表示这场运行中的请求执行成功，不代表答案全部正确。正在运行的测试请到“测试 → 智商测试”查看实时看板。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/iq-history.webp"><img src="'+i+'" alt="测试历史列表，展示一场两道题两个参与者全部执行成功的运行"></a></p><figcaption>本例包含 2 道题和 2 个参与者，共 4 次调用；点击该行“运行详情”继续查看。</figcaption></figure><h2 id="打开运行详情" tabindex="-1">打开运行详情 <a class="header-anchor" href="#打开运行详情" aria-label="Permalink to &quot;打开运行详情&quot;">​</a></h2><p>点击某条历史记录的“运行详情”，查看题目、参与者、调用状态和耗时。找到需要查看的调用，点击“查看输出”或“查看详情”。</p><p>输出回放展示本次执行时保存的模型、站点、连接地址、推理强度和 IQ 参数快照。之后修改或删除站点，不会把历史快照替换为当前配置。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/iq-results.webp"><img src="'+o+'" alt="已完成测试的运行详情，按题目列出四次调用、耗时及查看输出按钮"></a></p><figcaption>已完成运行的详情。按题目找到参与者，查看单次调用的结果、耗时并打开输出。</figcaption></figure><h2 id="查看输出和每次尝试" tabindex="-1">查看输出和每次尝试 <a class="header-anchor" href="#查看输出和每次尝试" aria-label="Permalink to &quot;查看输出和每次尝试&quot;">​</a></h2><p>发生重试时，可以在尝试选择器中切换“第 n 次”，检查每次尝试的状态、输出和错误。不要只根据最后一次结果推断前几次发生了什么。</p><p>详情提供输出内容与可用的原始流入口。输出包含可展示的代码或其他产物时，可通过页面提供的预览切换阅读；需要核对传输细节时查看原始流文件。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/iq-output.webp"><img src="'+p+'" alt="输出回放中展示模型演示回答、思考内容、原题及参考答案"></a></p><figcaption>① 阅读模型的回答与思考内容；② 展开参考答案进行人工比较。图中回答来自本地演示服务。</figcaption></figure><p>原始流或产物缺失时，记录摘要可能仍然存在。查看页面提示，确认运行是否曾中止，以及关联文件是否被移动或删除。</p><h2 id="删除历史运行" tabindex="-1">删除历史运行 <a class="header-anchor" href="#删除历史运行" aria-label="Permalink to &quot;删除历史运行&quot;">​</a></h2><p>在列表中使用删除图标并确认，会同时删除这次运行的记录、原始流文件和产物，删除后无法从应用内恢复。</p><p>删除一场测试不会删除当前题库。探测记录页的“清理全部探测记录”属于另一套数据，不用于删除 IQ 测试历史。</p>',18)])])}const m=a(u,[["render",l]]);export{g as __pageData,m as default};
